// 모듈 입력: user, results
const results = [...(Array.isArray($json.results) ? $json.results : [])].sort((a, b) => a.index - b.index);
const user = String($json.user ?? '').trim();
const ICON = { '자동 답변': '✅', '접수 완료': '📝', '등록 완료': '📅', '거절': '⛔', '입력 필요': '❓', '담당자 연결': '🙋' };
const oneLine = value => String(value ?? '').replace(/\s+/g, ' ').trim();
// 여러 줄 답(SNS 채널별 글)은 줄을 살려 들여 쓴다
const block = value => String(value ?? '').split('\n').map(oneLine).filter(Boolean).join('\n   ');
const lines = results.map(r => `${r.index}. ${ICON[r.route] ?? '•'} [${r.route}] ${block(r.answer)}`);
const ask = results.filter(r => r.route === '입력 필요').map(r => r.index);
const handed = results.filter(r => r.route === '담당자 연결').map(r => r.index);
const tail = [];
if (ask.length) tail.push(`❓ ${ask.join(', ')}번은 필요한 정보를 알려 주시면 바로 처리할게요.`);
if (handed.length) tail.push(`🙋 ${handed.join(', ')}번은 담당자가 이어서 연락드립니다.`);
const reply = [`${user} 님, 요청하신 ${results.length}가지를 정리했어요.`, ...lines, ...tail].join('\n');
return [{ json: { count: results.length, results, reply } }];
